private static Task EchoHeaders(HttpContext context)
    {
        foreach (var h in context.Request.Headers)
            context.Response.Headers.Add(h);
        context.Response.StatusCode = (int)HttpStatusCode.OK;
        return context.Response.WriteAsync("Hello from Fabrizio");
    }

public static StringBuilder AppendNext(this StringBuilder builder, string next, char separator = ',')
    {
        if (builder.Length > 0)
        {
            builder.Append(separator);
        }

        return builder.Append(next);
    }

private Task WhenIGetUrlOnTheApiGatewayMultipleTimes(string url, int times, string cookie, string value)
    {
        var tasks = new Task[times];
        for (var i = 0; i < times; i++)
        {
            tasks[i] = GetParallelTask(url, cookie, value);
        }

        return Task.WhenAll(tasks);
    }

