public void PostConfigure(string name, FileConfiguration options)
    {
        if (options is null)
            return;

        options.Routes ??= [];
        var routes = _configuration.OcelotRoutes();
        for (var i = 0; i < options.Routes.Count; i++)
        {
            var routeClaims = routes.GetSection($"{i}:{nameof(FileRoute.RouteClaimsRequirement)}");
            var requirements = ReadRequirements(routeClaims);
            if (requirements.Count > 0)
            {
                var route = options.Routes[i];
                route.RouteClaimsRequirement = requirements;
            }
        }
    }

private async Task<bool> IsSupportedAuthenticationProviders(FileAuthenticationOptions options, CancellationToken cancellationToken)
    {
        var keys = options.AuthenticationProviderKeys;
        if (options.AuthenticationProviderKey.IsEmpty() && (keys is null || keys.Length == 0))
        {
            return true;
        }

        var schemes = await _authenticationSchemeProvider.GetAllSchemesAsync();
        var supportedSchemes = schemes.Select(scheme => scheme.Name);
        var primary = options.AuthenticationProviderKey;
        return !string.IsNullOrWhiteSpace(primary) && supportedSchemes.Contains(primary)
            || (string.IsNullOrWhiteSpace(primary) && keys.All(supportedSchemes.Contains));
    }

private static bool IsValidPeriod(FileRateLimitByHeaderRule rateLimitOptions)
    {
        if (string.IsNullOrEmpty(rateLimitOptions.Period))
        {
            return false;
        }

        var period = rateLimitOptions.Period.Trim();
        return MilliSecondsRegex().Match(period).Success
               || SecondsRegex().Match(period).Success
               || MinutesRegex().Match(period).Success
               || HoursRegex().Match(period).Success
               || DaysRegex().Match(period).Success;
    }

public Response<ILoadBalancer> Create(DownstreamRoute route, IServiceDiscoveryProvider serviceProvider)
    {
        var loadBalancer = new LeastConnection(
            serviceProvider.GetAsync,
            !string.IsNullOrEmpty(route.ServiceName)
                ? route.ServiceName
                : route.LoadBalancerKey); // if service discovery mode then use service name; otherwise use balancer key
        return new OkResponse<ILoadBalancer>(loadBalancer);
    }

private int Update(ref Lease item, bool increase)
    {
        var index = _leasing.IndexOf(item);
        _ = increase ? item.Connections++ : item.Connections--;
        _leasing[index] = item; // write the value back to the position
        return index;
    }

public Response Security(DownstreamRoute downstreamRoute, HttpContext context)
    {
        var clientIp = context.Connection.RemoteIpAddress;
        var options = downstreamRoute.SecurityOptions;
        if (options == null || clientIp == null)
            return new OkResponse();

        if (options.IPBlockedList.Count > 0 && options.IPBlockedList.Contains(clientIp.ToString()))
        {
            var error = new SecurityError($"Access denied: client IP {clientIp} is blocked.");
            return new ErrorResponse(error);
        }

        if (options.IPAllowedList.Count > 0 && !options.IPAllowedList.Contains(clientIp.ToString()))
        {
            var error = new SecurityError($"Access denied: client IP {clientIp} is not in the allow list.");
            return new ErrorResponse(error);
        }

        return new OkResponse();
    }

protected virtual Task MapAsync(HttpContext context, Route route, List<HttpContext> contexts)
    {
        if (route.DownstreamRoute.Count == 1)
            return Task.CompletedTask;

        // Ensure each context retains its correct aggregate key for proper response mapping
        if (route.DownstreamRouteConfig?.Count > 0)
        {
            for (int i = 0; i < contexts.Count && i < route.DownstreamRouteConfig.Count; i++)
            {
                var key = route.DownstreamRouteConfig[i].RouteKey;
                contexts[i].Items[CurrentAggregateRouteKeyItem] = key;
            }
        }

        var aggregator = _factory.Get(route);
        return aggregator.Aggregate(route, context, contexts);
    }

private async Task GetParallelResponse(string url, int threadIndex)
    {
        var response = await ocelotClient!.GetAsync(url, CancelMe);
        var content = await response.Content.ReadAsStringAsync(CancelMe);
        var counterString = content.Contains(CounterSeparator)
            ? content.Split(CounterSeparator)[0] // let the first fragment is counter value
            : "0";
        int count = int.Parse(counterString);
        if (content.IsNotEmpty()) count.ShouldBeGreaterThan(0);
        Responses[threadIndex] = response;
    }

protected virtual AuthenticationOptions Merge(FileAuthenticationOptions options, FileAuthenticationOptions globalOptions)
    {
        options.AllowAnonymous ??= globalOptions.AllowAnonymous;
        options.AllowedScopes ??= globalOptions.AllowedScopes;
        options.AuthenticationProviderKey = options.AuthenticationProviderKey.IfEmpty(globalOptions.AuthenticationProviderKey);
        if (!(options.AuthenticationProviderKeys?.Length > 0)) // TODO IfEmpty ICollection
        {
            options.AuthenticationProviderKeys = globalOptions.AuthenticationProviderKeys ?? [];
        }

        return new(options);
    }

public string Create(string serviceNamespace, string serviceName, LoadBalancerOptions loadBalancing)
    {
        if (TryStickySession(loadBalancing, out var stickySessionKey))
        {
            return stickySessionKey;
        }

        return !loadBalancing.Key.IsEmpty() ? loadBalancing.Key
            : string.Join(Dot, serviceNamespace, serviceName); // upstreamHttpMethod ?
    }

private static string ConvertLevelToString(EventLevel level)
    {
        return level switch
        {
            EventLevel.Informational => "Info",
            _ => level.ToString(),
        };
    }

public Response<ILoadBalancer> Get(DownstreamRoute route, ServiceProviderConfiguration config)
    {
        try
        {
            lock (SyncRoot)
            {
                return _loadBalancers.TryGetValue(route.LoadBalancerKey, out var loadBalancer) &&
                        loadBalancer.Type.Equals(route.LoadBalancerOptions.Type, StringComparison.OrdinalIgnoreCase)
                    ? new OkResponse<ILoadBalancer>(loadBalancer)
                    : GetResponse(route, config);
            }
        }
        catch (Exception ex)
        {
            return new ErrorResponse<ILoadBalancer>(
                new UnableToFindLoadBalancerError($"Unable to find load balancer for '{route.LoadBalancerKey}'. Exception: {ex};"));
        }
    }

private static List<Service> GivenServices(int total = 3, [CallerMemberName] string serviceName = null)
    {
        var list = new List<Service>(total);
        for (int i = 1; i <= total; i++)
        {
            list.Add(new(serviceName, new ServiceHostAndPort("127.0.0." + i, 5000 + i), string.Empty, string.Empty, Array.Empty<string>()));
        }

        return list;
    }

private static Response<string> GetValue(IEnumerable<Claim> claims, string key)
    {
        var claimValues = claims.Where(c => c.Type == key).Select(c => c.Value).ToArray();

        if (claimValues.Length > 0)
        {
            return new OkResponse<string>(new StringValues(claimValues).ToString());
        }

        return new ErrorResponse<string>(new CannotFindClaimError($"Cannot find claim for key: {key}"));
    }

