        int index = upstreamUrlPath.IndexOf(Slash, 1);
        return index != -1
            ? upstreamUrlPath[index..]
            : Slash.ToString();
    }

protected virtual int GetDelay(FileConfiguration configuration)
    {
        var discoveryOpts = configuration?.GlobalConfiguration?.ServiceDiscoveryProvider;
        if (discoveryOpts != null && discoveryOpts.PollingInterval > 0)
            return discoveryOpts.PollingInterval;

        var internalConfig = _internalRepository.Get();
        var discoveryConfig = internalConfig?.ServiceProviderConfiguration;
        return (discoveryConfig != null && discoveryConfig.PollingInterval > 0)
            ? discoveryConfig.PollingInterval
            : DelayMilliseconds;
    }

private async Task<AuthenticateResult> AuthenticateAsync(HttpContext context, DownstreamRoute route)
    {
        var notEmptySchemes = route.AuthenticationOptions.AuthenticationProviderKeys
            .Where(s => !string.IsNullOrWhiteSpace(s));
        AuthenticateResult result = null;
        foreach (var scheme in notEmptySchemes)
        {
            try
            {
                result = await context.AuthenticateAsync(scheme);
                if (result?.Succeeded == true)
                {
                    return result;
                }
            }
            catch (Exception e)
            {
                Logger.LogWarning(() =>
                    $"Unable to authenticate the client for route '{route.Name()}' using the {scheme} authentication scheme due to error: {e.Message}");
            }
        }

        return result ?? AuthenticateResult.NoResult();
    }

public static T OcelotJProperty<T>(this JObject route, string propertyPath, JObject globalConfiguration = null)
    {
        globalConfiguration ??= MergedConfigJObject.OcelotJSection(nameof(FileConfiguration.GlobalConfiguration)) as JObject;
        JToken prop = route?.SelectToken(propertyPath);
        JToken glob = globalConfiguration?.SelectToken(propertyPath);
        if (prop is not null && prop.Type != JTokenType.Null)
            return prop.ToObject<T>();

        return glob is not null && glob.Type != JTokenType.Null
            ? glob.ToObject<T>()
            : default;
    }

public async Task SetAsync(FileConfiguration configuration, CancellationToken cancellationToken = default)
    {
        var json = JsonConvert.SerializeObject(configuration, Formatting.Indented);
        await _semaphore.WaitAsync(cancellationToken);
        try
        {
            if (_environmentFile.Exists)
                _environmentFile.Delete();

            await FileIO.WriteAllTextAsync(_environmentFile.FullName, json, cancellationToken);

            if (_ocelotFile.Exists)
                _ocelotFile.Delete();

            await FileIO.WriteAllTextAsync(_ocelotFile.FullName, json, cancellationToken);
        }
        finally
        {
            _semaphore.Release();
        }

        _changeTokenSource.Activate();
    }

protected override async Task SerializeToStreamAsync(Stream stream, TransportContext context)
    {
        var remaining = _size;
        while (remaining > 0)
        {
            var count = (int)Math.Min(remaining, _dataBuffer.Length);
            await stream.WriteAsync(_dataBuffer, 0, count);
            remaining -= count;
        }
    }

private HeaderFindAndReplace Map(Header input)
    {
        var findAndReplace = input.Value.Split(HeaderFindAndReplace.Comma);
        var replace = findAndReplace[1].TrimStart();

        var startOfPlaceholder = replace.IndexOf(Placeholders.OpeningBrace, StringComparison.Ordinal);
        if (startOfPlaceholder > -1)
        {
            var endOfPlaceholder = replace.IndexOf(Placeholders.ClosingBrace, startOfPlaceholder);
            var placeholder = replace.Substring(startOfPlaceholder,
                                                endOfPlaceholder - startOfPlaceholder + 1);
            var value = _placeholders.Get(placeholder);
            if (value.IsError)
            {
                _logger.LogWarning(() => $"{nameof(HeaderFindAndReplace)} was not mapped from {input} due to {value.Errors.ToErrorString()}");
                return null;
            }

            replace = replace.Replace(placeholder, value.Data);
        }

        return new(input.Key, findAndReplace[0], replace, 0);
    }
